//! Oracle tier: reads Goldmark artifacts regenerated by
//! `scripts/regen-fixtures.py` (see docs/FIXTURES.md).
#![cfg(feature = "oracle-fixtures")]
use d2_rs_text::markdown::delimiter::scan_delimiter;
use serde::Deserialize;
use serde_json::Value;
#[derive(Deserialize)]
#[serde(rename_all = "PascalCase")]
struct Request {
    line: String,
    before: i32,
    minimum: isize,
    allowed: String,
}
#[derive(Deserialize)]
struct Fixture {
    requests: Vec<Request>,
    results: Vec<Value>,
}
#[test]
fn pinned_goldmark_delimiter_scanning() {
    let f: Fixture = serde_json::from_str(d2_rs_testdata::oracle_fixture!(
        "tests/fixtures/delimiter.json"
    ))
    .unwrap();
    assert!(!f.requests.is_empty());
    assert_eq!(f.requests.len(), f.results.len());
    for (i, (q, expected)) in f.requests.iter().zip(f.results).enumerate() {
        let line: Vec<_> = (0..q.line.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&q.line[i..i + 2], 16).unwrap())
            .collect();
        let actual = scan_delimiter(&line, q.before, q.minimum, q.allowed.as_bytes());
        assert_eq!(serde_json::to_value(actual).unwrap(), expected, "case {i}");
    }
}

#[test]
fn pinned_goldmark_delimiter_consumption() {
    use d2_rs_text::markdown::delimiter::Delimiter;
    #[derive(Deserialize)]
    #[serde(rename_all = "PascalCase")]
    struct Request {
        opener: Delimiter,
        closer: Delimiter,
        count: isize,
    }
    #[derive(Deserialize)]
    struct Fixture {
        requests: Vec<Request>,
        results: Vec<Value>,
    }
    let f: Fixture = serde_json::from_str(d2_rs_testdata::oracle_fixture!(
        "tests/fixtures/delimiter-consumption.json"
    ))
    .unwrap();
    assert!(!f.requests.is_empty());
    assert_eq!(f.requests.len(), f.results.len());
    for (i, (mut q, expected)) in f.requests.into_iter().zip(f.results).enumerate() {
        let before = q.opener.calc_consumption(&q.closer);
        q.opener.consume_characters(q.count);
        q.closer.consume_characters(q.count);
        let after = q.opener.calc_consumption(&q.closer);
        assert_eq!(
            serde_json::json!({"before":before,"after":after,"opener":q.opener,"closer":q.closer}),
            expected,
            "case {i}"
        );
    }
}
